import fs from "fs";
import path from "path";
import { execFile } from "child_process";
import util from "util";
import { getFfmpegBinary } from "./videoService";

/**
 * Clip "style" effects layered on in the effects pass: generated music per
 * mood (with an exact beat grid for beat sync), generated sound effects,
 * voice clean-up, colour grades and cut transitions. Everything is
 * generated by ffmpeg — no licensed assets — and cached under data/.
 * Real tracks dropped in data/music/<mood>/ replace the generated ones.
 */

const execFileP = util.promisify(execFile);
const ffmpegBin = () => getFfmpegBinary();

export * from "./clipStyleOptions";
import { ClipStyle, MusicMood, ColorGrade, CutTransition, FilmLook, FitBackground } from "./clipStyleOptions";

// ---- mood picking ----------------------------------------------------------

const MOOD_WORDS: Record<Exclude<MusicMood, "auto">, RegExp> = {
  funny: /\b(funny|laugh|lol|joke|hilarious|crazy|weird|ridiculous|stupid|dumb|awkward|prank)\b/g,
  dramatic: /\b(died|death|dead|war|fear|scary|danger|lost|tragic|cancer|crisis|failed|fired|broke|alone|dark|pain)\b/g,
  hype: /\b(money|million|billion|win|winning|crush|insane|massive|grind|beast|power|fast|rich|dominate|best)\b/g,
  inspiring: /\b(dream|believe|hope|change|future|grow|purpose|love|journey|learn|success|goal|proud|life)\b/g,
  chill: /\b(calm|relax|morning|coffee|peace|slow|simple|nature|quiet|easy|routine)\b/g,
  lofi: /\b(study|focus|work|night|code|coding|productive|deep|book|read|writing)\b/g,
};

/** Pick a music mood from what's said in the clip (no API call). */
export function pickMood(text: string): Exclude<MusicMood, "auto"> {
  const t = text.toLowerCase();
  let best: Exclude<MusicMood, "auto"> = "chill";
  let score = 0;
  for (const [mood, re] of Object.entries(MOOD_WORDS) as [Exclude<MusicMood, "auto">, RegExp][]) {
    const n = (t.match(re) || []).length;
    if (n > score) {
      score = n;
      best = mood;
    }
  }
  return best;
}

// ---- generated music -------------------------------------------------------

type Chord = [number, number, number, number]; // bass root, then 3 chord tones
const MINOR_PROG: Chord[] = [
  [110, 220, 261.63, 329.63], // Am
  [87.31, 174.61, 220, 261.63], // F
  [130.81, 261.63, 329.63, 392], // C
  [98, 196, 246.94, 293.66], // G
];
const MAJOR_PROG: Chord[] = [
  [130.81, 261.63, 329.63, 392], // C
  [98, 196, 246.94, 293.66], // G
  [110, 220, 261.63, 329.63], // Am
  [87.31, 174.61, 220, 261.63], // F
];

interface MoodSpec {
  bpm: number;
  prog: Chord[];
  kick: number; // 0..1, 0 = none
  kickEvery: 1 | 4; // every beat, or once per bar
  hat: number;
  clap: number;
  bass: number;
  pad: number;
  pluck: boolean; // short plucked chords instead of a held pad
  lowpass: number;
}

const MOODS: Record<Exclude<MusicMood, "auto">, MoodSpec> = {
  hype: { bpm: 126, prog: MINOR_PROG, kick: 0.55, kickEvery: 1, hat: 0.07, clap: 0.18, bass: 0.2, pad: 0.05, pluck: false, lowpass: 3200 },
  chill: { bpm: 88, prog: MAJOR_PROG, kick: 0.3, kickEvery: 1, hat: 0.04, clap: 0, bass: 0.14, pad: 0.06, pluck: false, lowpass: 1600 },
  lofi: { bpm: 78, prog: MINOR_PROG, kick: 0.32, kickEvery: 1, hat: 0.035, clap: 0.08, bass: 0.15, pad: 0.06, pluck: false, lowpass: 950 },
  dramatic: { bpm: 70, prog: MINOR_PROG, kick: 0.5, kickEvery: 4, hat: 0, clap: 0, bass: 0.22, pad: 0.09, pluck: false, lowpass: 1300 },
  inspiring: { bpm: 100, prog: MAJOR_PROG, kick: 0.4, kickEvery: 1, hat: 0.05, clap: 0.06, bass: 0.16, pad: 0.07, pluck: false, lowpass: 2600 },
  funny: { bpm: 112, prog: MAJOR_PROG, kick: 0.35, kickEvery: 1, hat: 0.05, clap: 0.12, bass: 0.18, pad: 0.09, pluck: true, lowpass: 2800 },
};

const n = (x: number) => x.toFixed(4);
/** if-chain picking chord[k] by chord index c (0..3). */
const byChord = (prog: Chord[], k: number) =>
  `if(lt(c\\,1)\\,${n(prog[0][k])}\\,if(lt(c\\,2)\\,${n(prog[1][k])}\\,if(lt(c\\,3)\\,${n(prog[2][k])}\\,${n(prog[3][k])})))`;

/** aevalsrc expression for a mood loop (commas escaped for a filtergraph). */
export function moodExpression(spec: MoodSpec): string {
  const beat = 60 / spec.bpm;
  const bar = beat * 4;
  // c = chord index; mb/mt = time within the beat / bar.
  const c = `mod(floor(t/${n(bar)})\\,4)`;
  const sub = (e: string) => e.replace(/\bc\b/g, c);
  const mb = `mod(t\\,${n(beat)})`;
  const mt = `mod(t\\,${n(bar)})`;
  // Envelope that reaches 0 at bar edges, so chord changes don't click.
  const barEdge = `min(1\\,min(${mt}/0.04\\,(${n(bar)}-${mt})/0.04))`;
  const beatEdge = `min(1\\,${mb}/0.006)*(1-${mb}/${n(beat)})`;
  const parts: string[] = [];
  const padEnv = spec.pluck ? `exp(-7*${mb})*${beatEdge}` : `${barEdge}*(0.75+0.25*sin(2*PI*t/${n(bar)}))`;
  parts.push(
    `${n(spec.pad)}*${padEnv}*(` +
      [1, 2, 3].map((k) => `sin(2*PI*${sub(byChord(spec.prog, k))}*t)`).join("+") +
      `)`
  );
  if (spec.bass > 0) {
    parts.push(`${n(spec.bass)}*sin(2*PI*${sub(byChord(spec.prog, 0))}*t)*exp(-2.2*${mb})*${beatEdge}`);
  }
  if (spec.kick > 0) {
    const mk = spec.kickEvery === 4 ? mt : mb;
    parts.push(`${n(spec.kick)}*sin(2*PI*(45*${mk}+18*(1-exp(-25*${mk}))))*exp(-9*${mk})`);
  }
  if (spec.hat > 0) {
    const mh = `mod(t+${n(beat / 2)}\\,${n(beat)})`; // off-beat 8ths
    parts.push(`${n(spec.hat)}*(random(0)*2-1)*exp(-70*${mh})`);
  }
  if (spec.clap > 0) {
    const mc = `mod(t+${n(beat)}\\,${n(beat * 2)})`; // beats 2 and 4
    parts.push(`${n(spec.clap)}*(random(1)*2-1)*exp(-22*${mc})`);
  }
  return parts.join("+");
}

const DATA = () => path.join(process.cwd(), "data");

/**
 * A music track for a mood. Real tracks in data/music/<mood>/ win (picked
 * at random; "...-120bpm.mp3" in the name enables beat sync). Otherwise a
 * generated loop of whole bars, with an exact bpm.
 */
export async function ensureMoodTrack(mood: Exclude<MusicMood, "auto">): Promise<{ path: string; bpm: number | null } | null> {
  const dir = path.join(DATA(), "music", mood);
  try {
    const real = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => /\.(mp3|m4a|wav|ogg)$/i.test(f)) : [];
    if (real.length) {
      const f = real[Math.floor(Math.random() * real.length)];
      const m = /(\d{2,3})\s*bpm/i.exec(f);
      return { path: path.join(dir, f), bpm: m ? Number(m[1]) : null };
    }
  } catch {}
  const spec = MOODS[mood];
  const out = path.join(DATA(), "music", `gen-${mood}-v2.mp3`);
  if (fs.existsSync(out)) return { path: out, bpm: spec.bpm };
  try {
    fs.mkdirSync(path.dirname(out), { recursive: true });
    const bar = (60 / spec.bpm) * 4;
    const bars = Math.max(8, Math.round(64 / bar));
    const dur = bars * bar;
    await execFileP(
      ffmpegBin(),
      [
        "-hide_banner", "-loglevel", "error", "-y",
        "-f", "lavfi", "-i", `aevalsrc='${moodExpression(spec)}':s=44100:d=${dur.toFixed(4)}`,
        "-af", `lowpass=f=${spec.lowpass},highpass=f=35,alimiter=limit=0.9`,
        "-ac", "2", "-c:a", "libmp3lame", "-b:a", "128k", out,
      ],
      { maxBuffer: 16 * 1024 * 1024, timeout: 120000 }
    );
    return fs.existsSync(out) ? { path: out, bpm: spec.bpm } : null;
  } catch (e) {
    console.warn(`[ClipStyle] Could not generate ${mood} music:`, e);
    return null;
  }
}

// ---- generated sound effects ---------------------------------------------

export type SfxKind = "whoosh" | "pop" | "ding" | "riser" | "scratch" | "boom" | "beep" | "rewind";
const SFX_SPECS: Record<SfxKind, { expr: string; d: number; af: string }> = {
  whoosh: { expr: "(random(0)*2-1)*pow(sin(PI*t/0.5)\\,2)*0.9", d: 0.5, af: "highpass=f=500,lowpass=f=4500" },
  pop: { expr: "sin(2*PI*(420*t+110*(1-exp(-35*t))))*exp(-28*t)*0.9", d: 0.14, af: "highpass=f=150" },
  ding: { expr: "(0.6*sin(2*PI*1318.5*t)*exp(-5*t)+0.25*sin(2*PI*2637*t)*exp(-8*t))", d: 0.9, af: "highpass=f=300" },
  scratch: { expr: "(random(0)*2-1)*sin(PI*t/0.55)*(0.55+0.45*sin(2*PI*16*t))*0.9", d: 0.55, af: "bandpass=f=1900:width_type=h:w=1700,volume=2" },
  boom: { expr: "sin(2*PI*(48*t+60*(1-exp(-14*t))/14))*exp(-3.2*t)*0.95", d: 1.3, af: "lowpass=f=420" },
  beep: { expr: "0.6*sin(2*PI*1000*t)", d: 2.5, af: "anull" },
  rewind: { expr: "((random(0)*2-1)*0.3+0.5*sin(2*PI*(1400*t-500*t*t)))*sin(PI*t/0.7)", d: 0.7, af: "highpass=f=300,lowpass=f=5000" },
  riser: { expr: "((random(0)*2-1)*0.35+0.45*sin(2*PI*(220*t+260*t*t)))*pow(t/1.4\\,2)", d: 1.4, af: "highpass=f=250,lowpass=f=6000" },
};

export async function ensureSfx(kind: SfxKind): Promise<string | null> {
  const out = path.join(DATA(), "sfx", `${kind}-v1.wav`);
  if (fs.existsSync(out)) return out;
  try {
    fs.mkdirSync(path.dirname(out), { recursive: true });
    const s = SFX_SPECS[kind];
    await execFileP(
      ffmpegBin(),
      ["-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", `aevalsrc='${s.expr}':s=44100:d=${s.d}`, "-af", s.af, "-ac", "2", out],
      { timeout: 60000 }
    );
    return fs.existsSync(out) ? out : null;
  } catch (e) {
    console.warn(`[ClipStyle] Could not generate ${kind} sfx:`, e);
    return null;
  }
}

export interface SfxEvent {
  kind: SfxKind;
  at: number; // clip-relative seconds
  gain: number;
}

const NUMBER_WORD = /\d|\b(hundred|thousand|million|billion|percent)\b/i;

/**
 * Where sound effects go: whooshes into transitions and B-roll, a pop on
 * key words, a ding on numbers, a riser into the end of the hook title.
 * Spaced out so it never turns into noise (max ~10 per clip).
 */
export function planSfx(opts: {
  words: { start: number; text: string }[];
  isKeyword: (w: string) => boolean;
  transitions: number[];
  brollStarts: number[];
  hookUntil?: number;
  duration: number;
  beats?: number[] | null;
}): SfxEvent[] {
  const ev: SfxEvent[] = [];
  const near = (t: number, gap: number) => ev.some((e) => Math.abs(e.at - t) < gap);
  for (const t of [...opts.transitions, ...opts.brollStarts]) {
    const at = Math.max(0, t - 0.25);
    if (!near(at, 0.6)) ev.push({ kind: "whoosh", at, gain: 0.45 });
  }
  if (opts.hookUntil && opts.hookUntil > 1.6) ev.push({ kind: "riser", at: opts.hookUntil - 1.4, gain: 0.22 });
  let pops = 0;
  let dings = 0;
  let lastPop = -10;
  let lastDing = -10;
  for (const w of opts.words) {
    if (w.start < 0.3 || w.start > opts.duration - 0.3) continue;
    const at = snapToBeat(w.start, opts.beats, 0.12);
    if (NUMBER_WORD.test(w.text) && dings < 3 && at - lastDing > 3 && !near(at, 0.5)) {
      ev.push({ kind: "ding", at, gain: 0.3 });
      dings++;
      lastDing = at;
    } else if (opts.isKeyword(w.text) && pops < 5 && at - lastPop > 2.5 && !near(at, 0.5)) {
      ev.push({ kind: "pop", at, gain: 0.35 });
      pops++;
      lastPop = at;
    }
  }
  return ev.sort((a, b) => a.at - b.at).slice(0, 12);
}

// ---- beats ----------------------------------------------------------------

export function beatGrid(bpm: number | null | undefined, duration: number): number[] | null {
  if (!bpm || bpm < 40 || bpm > 220) return null;
  const beat = 60 / bpm;
  const out: number[] = [];
  for (let t = 0; t <= duration + beat; t += beat) out.push(Number(t.toFixed(3)));
  return out;
}

/** Move t onto the nearest beat if one is within `tol` seconds. */
export function snapToBeat(t: number, beats: number[] | null | undefined, tol = 0.2): number {
  if (!beats?.length) return t;
  let best = t;
  let d = tol;
  for (const b of beats) {
    const x = Math.abs(b - t);
    if (x <= d) {
      d = x;
      best = b;
    }
  }
  return best;
}

// ---- picture --------------------------------------------------------------

/** ffmpeg filter chain for a colour grade ("" for none). */
export function gradeFilter(g: ColorGrade): string {
  switch (g) {
    case "cinematic":
      return "colorbalance=rs=-0.04:bs=0.07:rh=0.07:bh=-0.05,eq=contrast=1.08:saturation=1.08";
    case "warm":
      return "colorbalance=rm=0.06:gm=0.01:bm=-0.06:rh=0.03:bh=-0.03,eq=saturation=1.08";
    case "punchy":
      return "eq=contrast=1.14:saturation=1.32:gamma=0.97,unsharp=5:5:0.5";
    case "moody":
      return "eq=contrast=1.12:brightness=-0.035:saturation=0.78,colorbalance=bs=0.05:bm=0.03";
    case "bw":
      return "hue=s=0,eq=contrast=1.16";
    default:
      return "";
  }
}

/** Filter chain flashing / glitching the frame around each time in `at`. */
export function transitionFilter(kind: CutTransition, at: number[]): string {
  if (kind === "none" || kind === "zoom" || at.length === 0) return "";
  const win = (half: number) => at.map((t) => `between(t\\,${(t - half).toFixed(3)}\\,${(t + half).toFixed(3)})`).join("+");
  if (kind === "flash") return `drawbox=x=0:y=0:w=iw:h=ih:color=white@0.75:t=fill:enable='${win(0.05)}'`;
  if (kind === "lightleak") {
    // Warm glow washing over the cut.
    return `colorbalance=rs=0.35:gs=0.12:bs=-0.25:rm=0.25:gm=0.05:bm=-0.15:enable='${win(0.2)}',eq=brightness=0.16:saturation=1.25:enable='${win(0.14)}'`;
  }
  if (kind === "burn") {
    // Over-exposed orange flare, like the end of a film reel.
    return `eq=brightness=0.42:contrast=1.5:saturation=1.7:enable='${win(0.07)}',colorbalance=rs=0.5:gs=0.12:bs=-0.45:rh=0.3:bh=-0.3:enable='${win(0.13)}'`;
  }
  if (kind === "rewind") {
    // VHS rewind: colour split, static, scan lines, washed-out colour.
    return `rgbashift=rh=-12:bh=12:enable='${win(0.22)}',noise=alls=40:allf=t:enable='${win(0.22)}',drawgrid=w=iw:h=6:t=2:c=black@0.35:enable='${win(0.22)}',eq=saturation=0.55:enable='${win(0.22)}'`;
  }
  if (kind === "whip") {
    // Fast sideways pan blur.
    return `avgblur=sizeX=70:sizeY=1:enable='${win(0.08)}'`;
  }
  // glitch: RGB split + noise for a few frames.
  return `rgbashift=rh=-16:bh=16:rv=4:enable='${win(0.09)}',noise=alls=45:allf=t:enable='${win(0.07)}'`;
}

export const STUDIO_VOICE_CHAIN = "highpass=f=75,afftdn=nf=-25,acompressor=threshold=0.125:ratio=3:attack=12:release=250:makeup=1.6";
export const LOUDNESS_CHAIN = "loudnorm=I=-14:TP=-1.5:LRA=11,aresample=48000";

// ---- film looks / fit backgrounds -----------------------------------------

/** ffmpeg chain for a film look ("" for none). */
export function filmLookFilter(look: FilmLook): string {
  switch (look) {
    case "grain":
      return "noise=alls=13:allf=t+u";
    case "vignette":
      return "vignette=PI/4.6";
    case "letterbox":
      return "drawbox=x=0:y=0:w=iw:h=ih*0.085:color=black:t=fill,drawbox=x=0:y=ih-ih*0.085:w=iw:h=ih*0.085:color=black:t=fill";
    case "vhs":
      return "rgbashift=rh=5:bh=-5,eq=saturation=1.35:contrast=1.06,noise=alls=11:allf=t,gblur=sigma=0.7,vignette=PI/5";
    case "silent":
      return "hue=s=0,eq=contrast=1.25:brightness='0.03*sin(t*37)':eval=frame,noise=alls=24:allf=t,vignette=PI/4";
    default:
      return "";
  }
}

/** Background chain for fitted (screen / wide) shots, applied to a full-frame scaled copy. */
export function fitBackgroundChain(kind: FitBackground | undefined, brandHex?: string): string {
  if (kind === "dark") return "gblur=sigma=30,eq=brightness=-0.2:saturation=0.6";
  if (kind === "brand") {
    const c = /^#[0-9a-fA-F]{6}$/.test(brandHex || "") ? `0x${brandHex!.slice(1)}` : "0xFACC15";
    return `gblur=sigma=34,eq=brightness=-0.12,drawbox=x=0:y=0:w=iw:h=ih:color=${c}@0.55:t=fill`;
  }
  return "gblur=sigma=24";
}

/** #RRGGBB -> ASS &H00BBGGRR. */
export function hexToAss(hex: string): string {
  const h = hex.replace("#", "");
  return `&H00${h.slice(4, 6)}${h.slice(2, 4)}${h.slice(0, 2)}`.toUpperCase();
}

// ---- profanity bleep ---------------------------------------------------------

const PROFANITY = /^(fuck\w*|motherfuck\w*|shit\w*|bullshit|bitch\w*|asshole\w*|bastard\w*|dick|dickhead|pussy|cunt\w*|damn|goddamn|crap|piss\w*|whore\w*|slut\w*|fag\w*|nigg\w*|retard\w*)$/i;

export function isProfane(word: string): boolean {
  return PROFANITY.test(word.replace(/[^A-Za-z]/g, ""));
}

/** "fucking" -> "f******"-style mask that keeps punctuation. */
export function maskProfanity(word: string): string {
  return word.replace(/[A-Za-z]+/, (m) => (m.length <= 2 ? "*".repeat(m.length) : m[0] + "*".repeat(m.length - 1)));
}

// ---- number counters -----------------------------------------------------

/** "$599", "50%", "10,000", "3x", "2.5k" -> parts for a count-up, or null. */
export function parseCounter(word: string): { prefix: string; value: number; decimals: number; suffix: string } | null {
  const w = word.trim().replace(/^["“(]+/, "").replace(/[.,!?;:"”)]+$/, "");
  const m = /^([$€£]?)(\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)(%|x|k|m|b|K|M|B)?$/.exec(w);
  if (!m) return null;
  const value = Number(m[2].replace(/,/g, ""));
  if (!Number.isFinite(value) || value < 3) return null;
  if (!m[1] && !m[3] && value >= 1900 && value <= 2100 && !m[2].includes(".")) return null; // a year
  const decimals = m[2].includes(".") ? m[2].split(".")[1].length : 0;
  return { prefix: m[1], value, decimals, suffix: m[3] || "" };
}

export function formatCounter(c: { prefix: string; decimals: number; suffix: string }, v: number): string {
  const n = c.decimals ? v.toFixed(c.decimals) : Math.round(v).toLocaleString("en-US");
  return `${c.prefix}${n}${c.suffix}`;
}

// ---- hype moments ----------------------------------------------------------

/**
 * The clip's most energetic moments: momentary loudness (EBU R128, 400ms)
 * peaks well above the clip's typical level, away from the opening hook
 * and the very end. Returns clip-relative times, strongest first.
 */
export async function detectHypeMoments(file: string, duration: number, max = 2): Promise<number[]> {
  try {
    const res: any = await execFileP(
      ffmpegBin(),
      ["-hide_banner", "-nostats", "-i", file, "-vn", "-af", "ebur128=framelog=info", "-f", "null", "-"],
      { maxBuffer: 64 * 1024 * 1024, timeout: 120000 }
    );
    const pts: { t: number; m: number }[] = [];
    const re = /t:\s*([\d.]+)\s+TARGET:[^M]*M:\s*(-?[\d.]+|-inf)/g;
    let mm: RegExpExecArray | null;
    const log = String(res.stderr || "");
    while ((mm = re.exec(log))) {
      const m = mm[2] === "-inf" ? -70 : Number(mm[2]);
      pts.push({ t: Number(mm[1]), m: Math.max(-70, m) });
    }
    if (pts.length < 10) return [];
    // 1s moving average (frames are 0.1s) so a single loud syllable doesn't win.
    const smooth = pts.map((p, i) => {
      const win = pts.slice(Math.max(0, i - 5), i + 5);
      return { t: p.t, m: win.reduce((s, x) => s + x.m, 0) / win.length };
    });
    const voiced = smooth.filter((p) => p.m > -45).map((p) => p.m).sort((a, b) => a - b);
    if (!voiced.length) return [];
    const median = voiced[Math.floor(voiced.length / 2)];
    const cand = smooth
      .filter((p) => p.t > 3.4 && p.t < duration - 2.5 && p.m > median + 2)
      .sort((a, b) => b.m - a.m);
    const out: number[] = [];
    for (const c of cand) {
      if (out.every((t) => Math.abs(t - c.t) > 5)) out.push(Number(Math.max(0, c.t - 0.3).toFixed(2)));
      if (out.length >= max) break;
    }
    return out;
  } catch (e) {
    console.warn("[ClipStyle] Hype detection failed:", e);
    return [];
  }
}

// ---- LLM helper (translation) ------------------------------------------------

async function chatText(prompt: string, keys: { groqKey?: string; openaiKey?: string }): Promise<string | null> {
  const openai = (keys.openaiKey || process.env.OPENAI_API_KEY || "").trim();
  if (openai) {
    try {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: { Authorization: `Bearer ${openai}`, "Content-Type": "application/json" },
        body: JSON.stringify({ model: process.env.OPENAI_TRANSLATE_MODEL || "gpt-4.1-mini", messages: [{ role: "user", content: prompt }] }),
        signal: AbortSignal.timeout(45000),
      });
      if (res.ok) {
        const data: any = await res.json();
        const text = data.choices?.[0]?.message?.content;
        if (text) return text;
      }
    } catch {}
  }
  const groq = (keys.groqKey || process.env.GROQ_API_KEY || "").trim();
  if (groq) {
    for (const model of ["openai/gpt-oss-120b", "openai/gpt-oss-20b"]) {
      try {
        const res = await fetch("https://api.groq.com/openai/v1/chat/completions", {
          method: "POST",
          headers: { Authorization: `Bearer ${groq}`, "Content-Type": "application/json" },
          body: JSON.stringify({ model, messages: [{ role: "user", content: prompt }], temperature: 0.2 }),
          signal: AbortSignal.timeout(45000),
        });
        if (res.ok) {
          const data: any = await res.json();
          const text = data.choices?.[0]?.message?.content;
          if (text) return text;
        }
      } catch {}
    }
  }
  return null;
}

const LANG_NAMES: Record<string, string> = {
  es: "Spanish", fr: "French", de: "German", pt: "Portuguese", it: "Italian", hi: "Hindi", ar: "Arabic",
  tr: "Turkish", ru: "Russian", ja: "Japanese", ko: "Korean", zh: "Simplified Chinese", id: "Indonesian",
};

/** Caption lines (same timing) translated into `lang`; null without an AI key or on failure. */
export async function translateLines(
  lines: { start: number; end: number; text: string }[],
  lang: string,
  keys: { groqKey?: string; openaiKey?: string }
): Promise<{ start: number; end: number; text: string }[] | null> {
  const name = LANG_NAMES[lang];
  if (!name || !lines.length) return null;
  const prompt =
    `Translate each caption line into natural, short spoken ${name}. Keep the meaning, no explanations.\n` +
    `Return ONLY a JSON array of strings, the same length and order as the input.\n\n` +
    JSON.stringify(lines.map((l) => l.text));
  const text = await chatText(prompt, keys);
  if (!text) return null;
  try {
    const m = /\[[\s\S]*\]/.exec(text);
    const arr = m ? JSON.parse(m[0]) : null;
    if (!Array.isArray(arr) || arr.length !== lines.length) return null;
    return lines.map((l, i) => ({ ...l, text: String(arr[i] || "").replace(/[{}\\\r\n]/g, " ").trim().slice(0, 120) }));
  } catch {
    return null;
  }
}

// ---- AI voiceover ------------------------------------------------------------

/** Narrator reading `text` (OpenAI text-to-speech). Returns {path, duration} or null. */
export async function generateVoiceover(text: string, openaiKey?: string): Promise<{ path: string; duration: number } | null> {
  const key = (openaiKey || process.env.OPENAI_API_KEY || "").trim();
  const line = text.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, "").trim().slice(0, 200);
  if (!key || !line) return null;
  const dir = path.join(DATA(), "voiceover");
  fs.mkdirSync(dir, { recursive: true });
  const out = path.join(dir, `vo-${Date.now()}-${Math.floor(Math.random() * 1e4)}.mp3`);
  for (const model of ["gpt-4o-mini-tts", "tts-1"]) {
    try {
      const res = await fetch("https://api.openai.com/v1/audio/speech", {
        method: "POST",
        headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          model,
          voice: "onyx",
          input: line,
          ...(model === "gpt-4o-mini-tts" ? { instructions: "Energetic, punchy social-media narrator. Fast but clear." } : {}),
        }),
        signal: AbortSignal.timeout(45000),
      });
      if (!res.ok) continue;
      fs.writeFileSync(out, Buffer.from(await res.arrayBuffer()));
      const dur = await probeDuration(out);
      if (dur > 0.3) return { path: out, duration: Math.min(dur, 8) };
    } catch {}
  }
  return null;
}

export async function probeDuration(file: string): Promise<number> {
  const res: any = await execFileP(ffmpegBin(), ["-hide_banner", "-i", file], { timeout: 30000 }).catch((e: any) => e);
  const m = /Duration:\s*(\d+):(\d+):([\d.]+)/.exec(String(res?.stderr || ""));
  return m ? Number(m[1]) * 3600 + Number(m[2]) * 60 + Number(m[3]) : 0;
}

